static struct TreeNode *build(int *preorder, int preStart, int preEnd, int *inorder, int inStart, int inEnd) {
  if (preStart > preEnd) return NULL;
  int rootVal = preorder[preStart];
  int idx = inStart;
  while (inorder[idx] != rootVal) idx++;
  int leftLen = idx - inStart;
  struct TreeNode *root = (struct TreeNode *)malloc(sizeof(struct TreeNode));
  root->val = rootVal;
  root->left = build(preorder, preStart + 1, preStart + leftLen, inorder, inStart, idx - 1);
  root->right = build(preorder, preStart + leftLen + 1, preEnd, inorder, idx + 1, inEnd);
  return root;
}

struct TreeNode *buildTree(int *preorder, int preorderSize, int *inorder, int inorderSize) {
  return build(preorder, 0, preorderSize - 1, inorder, 0, inorderSize - 1);
}

class Solution {
  TreeNode *build(vector<int> &preorder, int preStart, int preEnd, vector<int> &inorder, int inStart, int inEnd) {
    if (preStart > preEnd) return nullptr;
    int rootVal = preorder[preStart];
    int idx = inStart;
    while (inorder[idx] != rootVal) idx++;
    int leftLen = idx - inStart;
    TreeNode *root = new TreeNode(rootVal);
    root->left = build(preorder, preStart + 1, preStart + leftLen, inorder, inStart, idx - 1);
    root->right = build(preorder, preStart + leftLen + 1, preEnd, inorder, idx + 1, inEnd);
    return root;
  }

public:
  TreeNode *buildTree(vector<int> &preorder, vector<int> &inorder) {
    return build(preorder, 0, (int)preorder.size() - 1, inorder, 0, (int)inorder.size() - 1);
  }
};

func buildTree(preorder []int, inorder []int) *TreeNode {
	var build func(preStart, preEnd, inStart, inEnd int) *TreeNode
	build = func(preStart, preEnd, inStart, inEnd int) *TreeNode {
		if preStart > preEnd {
			return nil
		}
		rootVal := preorder[preStart]
		idx := inStart
		for inorder[idx] != rootVal {
			idx++
		}
		leftLen := idx - inStart
		root := &TreeNode{Val: rootVal}
		root.Left = build(preStart+1, preStart+leftLen, inStart, idx-1)
		root.Right = build(preStart+leftLen+1, preEnd, idx+1, inEnd)
		return root
	}
	return build(0, len(preorder)-1, 0, len(inorder)-1)
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private TreeNode build(int[] preorder, int preStart, int preEnd, int[] inorder, int inStart, int inEnd) {
    if (preStart > preEnd) return null;
    int rootVal = preorder[preStart];
    int idx = inStart;
    while (inorder[idx] != rootVal) idx++;
    int leftLen = idx - inStart;
    TreeNode root = new TreeNode(rootVal);
    root.left = build(preorder, preStart + 1, preStart + leftLen, inorder, inStart, idx - 1);
    root.right = build(preorder, preStart + leftLen + 1, preEnd, inorder, idx + 1, inEnd);
    return root;
  }

  public TreeNode buildTree(int[] preorder, int[] inorder) {
    return build(preorder, 0, preorder.length - 1, inorder, 0, inorder.length - 1);
  }
}

class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        def build(pre_start, pre_end, in_start, in_end):
            if pre_start > pre_end:
                return None
            root_val = preorder[pre_start]
            idx = in_start
            while inorder[idx] != root_val:
                idx += 1
            left_len = idx - in_start
            root = TreeNode(root_val)
            root.left = build(pre_start + 1, pre_start + left_len, in_start, idx - 1)
            root.right = build(pre_start + left_len + 1, pre_end, idx + 1, in_end)
            return root

        return build(0, len(preorder) - 1, 0, len(inorder) - 1)

impl Solution {
  pub fn build_tree(preorder: Vec<i32>, inorder: Vec<i32>) -> Option<Box<TreeNode>> {
    Self::build(&preorder, &inorder)
  }

  fn build(preorder: &[i32], inorder: &[i32]) -> Option<Box<TreeNode>> {
    if preorder.is_empty() {
      return None;
    }
    let root_val = preorder[0];
    let idx = inorder.iter().position(|&x| x == root_val).unwrap();
    let mut root = Box::new(TreeNode::new(root_val));
    root.left = Self::build(&preorder[1..1 + idx], &inorder[..idx]);
    root.right = Self::build(&preorder[1 + idx..], &inorder[idx + 1..]);
    Some(root)
  }
}

const buildTree = (preorder: number[], inorder: number[]): TreeNode | null => {
  const build = (preStart: number, preEnd: number, inStart: number, inEnd: number): TreeNode | null => {
    if (preStart > preEnd) return null;
    const rootVal = preorder[preStart];
    let idx = inStart;
    while (inorder[idx] !== rootVal) idx++;
    const leftLen = idx - inStart;
    const root = new TreeNode(rootVal);
    root.left = build(preStart + 1, preStart + leftLen, inStart, idx - 1);
    root.right = build(preStart + leftLen + 1, preEnd, idx + 1, inEnd);
    return root;
  };
  return build(0, preorder.length - 1, 0, inorder.length - 1);
};
